import pytest
from markupsafe import escape, Markup

# Test from test_escape.py
class Proxy:
    def __init__(self, value):
        self.__value = value

    @property
    def __class__(self):
        return self.__value.__class__

    def __str__(self):
        return str(self.__value)

def test_proxy():
    p = Proxy("test")
    assert p.__class__ is str
    assert isinstance(p, str)
    assert escape(p) == Markup("test")

class ReferenceStr(str):
    def __str__(self):
        return self

def test_subclass():
    s = ReferenceStr("test")
    assert isinstance(s, str)
    assert escape(s) == Markup("test")

# Test from test_markupsafe.py
def test_string_interpolation():
    assert Markup("<em>%s</em>") % "<bad user>" == "<em>&lt;bad user&gt;</em>"
    assert Markup("<em>%(username)s</em>") % {"username": "<bad user>"} == "<em>&lt;bad user&gt;</em>"

# Test from test_exception_custom_html.py
class CustomHtmlThatRaises:
    def __html__(self):
        raise ValueError(123)

def test_exception_custom_html():
    obj = CustomHtmlThatRaises()
    with pytest.raises(ValueError):
        escape(obj)

if __name__ == "__main__":
    test_proxy()
    test_subclass()
    test_string_interpolation()
    test_exception_custom_html()
    print("All tests passed!")

